"""Generate numerical assets with SciPy 1.14.1; not needed to run the GUI."""
import json
from pathlib import Path
from scipy.signal.windows import dpss

lengths = [512, 1000, 1024, 2000, 2048, 4000, 4096, 8192]
tapers = {n: dpss(n, 4, 7, sym=True, norm=2).tolist() for n in lengths}
target = Path(__file__).resolve().parents[1] / "vendor" / "dpss.js"
target.write_text(
    "// Generated by scripts/generate-tapers.py using SciPy 1.14.1. NW=4, K=7, L2 normalization.\n"
    "(function(r,d){if(typeof module==='object'&&module.exports)module.exports=d;else r.EEGTapers=d;})(globalThis,"
    + json.dumps(tapers, separators=(",", ":")) + ");\n",
    encoding="ascii",
)
